module.exports = function (RED) {
    function pti818dataAnalyzeNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        const fs = require('fs').promises; // 使用 promise 版本
        const iconv = require('iconv-lite');

        node.on("input", async function (msg) {
            try {
                const filePath = msg.payload;

                // 校验输入是否为字符串路径
                if (typeof filePath !== 'string') {
                    throw new Error('msg.payload must be a file path string');
                }

                node.log(`Reading CSV file: ${filePath}`);

                // 读取文件（原始 buffer）
                const buffer = await fs.readFile(filePath);

                // 转码：GB2312 -> UTF-8
                const csvText = iconv.decode(buffer, 'gb2312');

                // 解析 CSV 内容
                const result = parsePTI818CSV(csvText, node);

                // 输出结果
                msg.payload = result;
                node.send(msg);

            } catch (error) {
                node.error('Error processing CSV file: ' + error.message, msg);
                node.send([null, msg]); // 可选：发送到第二输出端口表示错误
            }
        });

        // CSV 解析函数（独立出来便于维护）
        function parsePTI818CSV(csvText, logger) {
            const lines = csvText.split('\n').map(line => line.trim().replace(/"/g, ''));
            let datas = {
                DateTime: "",
                ProgramId: "",
                User: "",
                DeviceId: "",
                FixtureId: "",
                LineId: "",
                ModelName: "",
                FixRetry: "",
                BoardId: "",
                BarCode: "",
                TestStat: "",
                OpenTest: "",
                ShortTest: "",
                CompTest: "",
                FunTest: "",
                TestTime: "",
                OpenFailCount: { Count: 0, Pins: [] },
                ShortFailCount: { Count: 0, Pins: [] },
                componentData: [],
                functionData: []
            };

            let OpenFailCount = 0;
            let ShortFailCount = 0;
            let compTestFlag = false;
            let compTestHeaderSeen = false;
            let functionFlag = false;
            let functionHeaderSeen = false;

            for (const line of lines) {
                if (!line) continue;

                const values = line.split(',');

                // 基础字段
                const key = values[0];
                if (key in datas && key !== 'OpenFailCount' && key !== 'ShortFailCount') {
                    datas[key] = values[1] || "";
                    continue;
                }

                // OpenFailCount
                if (key === "OpenFailCount") {
                    const count = parseInt(values[1]) || 0;
                    datas.OpenFailCount.Count = count;
                    OpenFailCount = count;
                    continue;
                }
                if (OpenFailCount > 0) {
                    datas.OpenFailCount.Pins.push(key);
                    OpenFailCount--;
                    continue;
                }

                // ShortFailCount
                if (key === "ShortFailCount") {
                    const count = parseInt(values[1]) || 0;
                    datas.ShortFailCount.Count = count;
                    ShortFailCount = count;
                    continue;
                }
                if (ShortFailCount > 0) {
                    datas.ShortFailCount.Pins.push(key);
                    ShortFailCount--;
                    continue;
                }

                // CompTest section
                if (key === "CompTest:") {
                    compTestFlag = true;
                    compTestHeaderSeen = false;
                    functionFlag = false;
                    continue;
                }

                if (compTestFlag && key === "STEP") {
                    compTestHeaderSeen = true;
                    continue;
                }

                if (compTestFlag && compTestHeaderSeen && key && key !== "FunTest:") {
                    if (values.length >= 22) {
                        datas.componentData.push({
                            STEP: values[0],
                            BX: values[1],
                            LC: values[2],
                            Flag: values[3],
                            Device: values[4],
                            STDval: values[5],
                            ACTval: values[6],
                            plusPercent: values[7],
                            minusPercent: values[8],
                            MD: values[9],
                            RG: values[10],
                            TM: values[11],
                            A: values[12],
                            B: values[13],
                            G1: values[14],
                            G2: values[15],
                            G3: values[16],
                            G4: values[17],
                            G5: values[18],
                            TestVal: values[19],
                            DevPercent: values[20],
                            Result: values[21],
                        });
                    }
                    continue;
                }

                // FunTest section
                if (key === "FunTest:") {
                    functionFlag = true;
                    functionHeaderSeen = false;
                    compTestFlag = false;
                    continue;
                }

                if (functionFlag && key === "Step") {
                    functionHeaderSeen = true;
                    continue;
                }

                if (functionFlag && functionHeaderSeen && key) {
                    if (values.length >= 14) {
                        datas.functionData.push({
                            STEP: values[0],
                            BX: values[1],
                            Descrip: values[2],
                            Module: values[3],
                            Type: values[4],
                            Function: values[5],
                            Delay: values[6],
                            Test: values[7],
                            DevPercent: values[8],
                            Std: values[9],
                            minusPercent: values[10],
                            plusPercent: values[11],
                            Result: values[12],
                            Info: values[13],
                        });
                    }
                    continue;
                }

                // LogEnd 表示一个完整记录结束（但这里我们只处理一个文件，所以可忽略）
                if (key === "LogEnd") {
                    break;
                }
            }

            return datas;
        }
    }

    RED.nodes.registerType("pti818dataAnalyze", pti818dataAnalyzeNode);
};